import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u11")
C = "A1-A2"

L(1, "Na sala de aula", "a aula, o professor, o quadro, os trabalhos de casa.",
  ["Nomear o vocabulário da sala de aula"],
  vocab=[V("v-les","les","aula|lição","noun","de","lessen"), V("v-klas","klas","turma|sala de aula","noun","de","klassen"),
         V("v-bord-school","bord","quadro","noun","het",note="O mesmo «bord» que prato; o contexto decide."), V("v-huiswerk","huiswerk","trabalhos de casa","noun","het"),
         V("v-woordenboek","woordenboek","dicionário","noun","het"), V("v-vraag","vraag","pergunta","noun","de","vragen"), V("v-antwoord","antwoord","resposta","noun","het","antwoorden")],
  ex=[("De les begint om negen uur.","A aula começa às nove."),("Ik heb een vraag.","Tenho uma pergunta."),("Wat is het antwoord?","Qual é a resposta?")],
  review=["v-leraar","v-student","v-school","v-schrift","v-pen"],
  cefr=C, exs=[
    MA([("les","aula"),("klas","turma"),("huiswerk","trabalhos de casa"),("woordenboek","dicionário"),("vraag","pergunta")], "Na escola.", ["v-les","v-klas","v-huiswerk","v-woordenboek","v-vraag"]),
    AR("huiswerk","os trabalhos de casa","het", "werk → het huiswerk.", ["v-huiswerk"]),
    AR("antwoord","a resposta","het", "«Het antwoord».", ["v-antwoord"]),
    AR("vraag","a pergunta","de", "«De vraag» — plural «vragen».", ["v-vraag"]),
    TR("pt-nl","Tenho uma pergunta.", ["Ik heb een vraag"], "een vraag.", ["v-vraag"]),
    TR("nl-pt","Wat is het antwoord?", ["Qual é a resposta"], "het antwoord.", ["v-antwoord"]),
    FB("De leraar schrijft op het ___.", ["bord"], "o quadro = het bord.", ["v-bord-school"], choices=["bord","huiswerk","antwoord"], tr="O professor escreve no quadro."),
    LI("Heb je je huiswerk gemaakt?", ["Heb je je huiswerk gemaakt"], "Fizeste os trabalhos de casa?", "huiswerk maken = fazer os TPC.", ["v-huiswerk"]),
    FE(["Ik","maak","mijn","huiswerk","in","de","woordenboek."], 5, "het", "«Het woordenboek» (boek → het).", ["v-woordenboek"]),
    WO("Há vinte alunos na turma.", ["Er","zijn","twintig","leerlingen","in","de","klas"], "er zijn + plural.", ["v-klas"]),
  ], diff=1, mins=5)

L(2, "Instruções do professor", "Lees, schrijf, luister, herhaal!",
  ["Perceber as instruções mais comuns numa aula"],
  vocab=[V("v-luisteren","luisteren","ouvir|escutar","verb",note="luisteren naar = ouvir (com atenção)"), V("v-openen-boek","openen","abrir","verb"),
         V("v-pagina","pagina","página","noun","de","pagina's"), V("v-oefening","oefening","exercício","noun","de","oefeningen"),
         V("v-samenwerken","samenwerken","trabalhar em conjunto","verb",note="Separável: we werken samen.")],
  ex=[("Open je boek op pagina twaalf.","Abre o livro na página doze."),("Luister goed!","Ouve com atenção!"),("Maak oefening drie.","Faz o exercício três."),("Werk samen met je buurman.","Trabalha com o teu colega do lado.")],
  gram=[G("g-imperativo-aula","Imperativo na aula","O imperativo é a **raiz** do verbo: *lees*, *schrijf*, *luister*, *open*, *maak*. Para vários alunos usa-se a mesma forma (às vezes com **jullie**: *Lezen jullie maar*). É direto, mas não é indelicado.",
    [("Herhaal na mij.","Repete depois de mim.")])],
  review=["v-lezen","v-schrijven","v-herhalen","v-boek","v-les"],
  cefr=C, exs=[
    MA([("luisteren","ouvir"),("openen","abrir"),("pagina","página"),("oefening","exercício")], "Na aula.", ["v-luisteren","v-openen-boek","v-pagina","v-oefening"]),
    TR("nl-pt","Open je boek op pagina twaalf.", ["Abre o (teu )livro na página doze","Abram o livro na página doze"], "op pagina = na página.", ["v-openen-boek","v-pagina"]),
    TR("pt-nl","Ouve com atenção!", ["Luister goed"], "Imperativo = raiz.", ["v-luisteren"]),
    MC("O professor diz «Herhaal na mij». O que faz?", ["*Repete o que ele diz","Escreve no caderno|Isso seria «schrijf».","Abre o livro|Isso seria «open je boek»."], "herhalen = repetir.", ["v-herhalen"]),
    FB("Maak ___ vier op pagina tien.", ["oefening"], "oefening = exercício.", ["v-oefening"], choices=["oefening","pagina","bord"], tr="Faz o exercício quatro na página dez."),
    AR("oefening","o exercício","de", "-ing → de.", ["v-oefening"]),
    FE(["Luisteren","goed!"], 0, "Luister", "Imperativo: luister.", ["v-luisteren"]),
    LI("Werk samen met je buurman.", ["Werk samen met je buurman"], "Trabalha com o teu colega do lado.", "samenwerken separado.", ["v-samenwerken"]),
    CJ("luisteren","ik","Ik ___ naar de leraar.", ["luister"], "luisteren → ik luister; luisteren naar = ouvir alguém.", ["v-luisteren"]),
    WO("Lê o texto em voz alta.", ["Lees","de","tekst","hardop","voor"], "voorlezen = ler em voz alta (separável).", ["v-lezen"]),
  ], diff=2, mins=5)

L(3, "Aprender uma língua", "Estudar, praticar, cometer erros e melhorar.",
  ["Falar da sua aprendizagem de neerlandês"],
  vocab=[V("v-studeren","studeren","estudar (num curso)","verb",note="Ik studeer rechten = estudo Direito."), V("v-oefenen","oefenen","praticar","verb"),
         V("v-fout","fout","erro","noun","de","fouten"), V("v-beter","beter","melhor","adjective"), V("v-uitspraak","uitspraak","pronúncia","noun","de")],
  ex=[("Ik oefen elke dag.","Pratico todos os dias."),("Ik maak nog veel fouten.","Ainda dou muitos erros."),("Mijn Nederlands wordt beter.","O meu neerlandês está a melhorar."),("De uitspraak is moeilijk.","A pronúncia é difícil.")],
  gram=[G("g-leren-studeren","Leren ou studeren?","**leren** = aprender algo (*ik leer Nederlands*). **studeren** = estudar num curso ou na universidade (*ik studeer medicijnen*). Para «estudar para um teste» diz-se **leren**: *ik moet leren voor mijn toets*.",
    [("Ik leer de woorden.","Estudo/aprendo as palavras.")],
    "Em português «estudar» serve para tudo; em neerlandês distingue-se.")],
  review=["v-leren","v-moeilijk","v-makkelijk","v-nederlands"],
  cefr=C, exs=[
    MA([("studeren","estudar (curso)"),("oefenen","praticar"),("fout","erro"),("uitspraak","pronúncia")], "Aprender.", ["v-studeren","v-oefenen","v-fout","v-uitspraak"]),
    MC("«Estudo Medicina na universidade» =", ["*Ik studeer medicijnen.","Ik leer medicijnen.|Para um curso usa-se «studeren»."], "studeren = curso.", ["v-studeren"]),
    MC("«Tenho de estudar para o teste» =", ["*Ik moet leren voor de toets.","Ik moet studeren voor de toets.|Ouve-se, mas o normal é «leren»."], "leren voor een toets.", ["v-leren"]),
    TR("pt-nl","Pratico todos os dias.", ["Ik oefen elke dag","Ik oefen iedere dag"], "oefenen → ik oefen.", ["v-oefenen"]),
    TR("nl-pt","Ik maak nog veel fouten.", ["Ainda [dou|faço|cometo] muitos erros"], "fouten maken = errar.", ["v-fout"]),
    AR("fout","o erro","de", "«De fout».", ["v-fout"]),
    FB("Mijn Nederlands wordt elke dag ___.", ["beter"], "beter = melhor.", ["v-beter"], choices=["beter","fout","moeilijk"], tr="O meu neerlandês melhora todos os dias."),
    LI("De uitspraak is niet makkelijk.", ["De uitspraak is niet makkelijk"], "A pronúncia não é fácil.", "uitspraak = pronúncia.", ["v-uitspraak"]),
    FE(["Ik","maak","veel","foutes."], 3, "fouten", "fout → fouten.", ["v-fout"]),
    SW("Escreva 2–3 frases sobre como aprende neerlandês (quando pratica, o que é difícil).", ["Ik leer Nederlands(.) Ik oefen elke dag(.) De uitspraak is moeilijk"],
       ["Usa «ik leer» ou «ik oefen»","Diz o que é difícil ou fácil","Verbo em 2.º lugar"], 6, "Modelo: «Ik leer Nederlands met een app. Ik oefen elke dag. De uitspraak is moeilijk, maar ik word beter.»", ["v-oefenen"]),
  ], diff=2, mins=6)

L(4, "O sistema escolar e os exames", "basisschool, middelbare school, toets, diploma.",
  ["Perceber termos básicos do ensino nos Países Baixos"],
  vocab=[V("v-basisschool","basisschool","escola primária","noun","de",note="Dos 4 aos 12 anos."), V("v-middelbare-school","middelbare school","escola secundária","noun","de"),
         V("v-toets","toets","teste","noun","de","toetsen"), V("v-examen","examen","exame","noun","het","examens"),
         V("v-cijfer","cijfer","nota","noun","het","cijfers",note="Escala de 1 a 10; 6 = suficiente."), V("v-slagen","slagen","passar (num exame)","verb",note="Ik ben geslaagd = passei.")],
  ex=[("Mijn dochter zit op de basisschool.","A minha filha anda na escola primária."),("Ik heb morgen een toets.","Amanhã tenho um teste."),("Ik heb een acht!","Tive um oito!","Escala de 1 a 10.")],
  gram=[G("g-cijfers","Notas de 1 a 10","Nos Países Baixos as notas vão de **1 a 10**. Um **6** é suficiente; um **8** já é muito bom; 10 é raríssimo. Diz-se *Ik heb een zeven* (tive um sete). Para «andar na escola» diz-se **op school zitten**: *ze zit op de basisschool*.",
    [("Een vijf is onvoldoende.","Um cinco é insuficiente.")],
    "Em Portugal a escala do secundário é de 0 a 20.")],
  review=["v-school","v-kind","v-dochter","v-zitten"],
  cefr=C, exs=[
    MA([("basisschool","escola primária"),("toets","teste"),("examen","exame"),("cijfer","nota")], "Escola.", ["v-basisschool","v-toets","v-examen","v-cijfer"]),
    MC("Num teste neerlandês, qual nota é suficiente?", ["*6","10|É a nota máxima.","12|A escala vai até 10."], "6 = voldoende.", ["v-cijfer"]),
    AR("examen","o exame","het", "«Het examen».", ["v-examen"]),
    AR("cijfer","a nota","het", "«Het cijfer».", ["v-cijfer"]),
    TR("pt-nl","Amanhã tenho um teste.", ["Morgen heb ik een toets","Ik heb morgen een toets"], "toets = teste.", ["v-toets"]),
    TR("nl-pt","Mijn zoon zit op de middelbare school.", ["O meu filho anda na (escola )secundária","O meu filho está no secundário"], "op school zitten = andar na escola.", ["v-middelbare-school"]),
    FB("Hoera, ik ben ___ voor mijn examen!", ["geslaagd"], "slagen → geslaagd (passei).", ["v-slagen"], choices=["geslaagd","gezakt","geleerd"], tr="Viva, passei no exame!"),
    LI("Ik heb een acht voor wiskunde.", ["Ik heb een acht voor wiskunde"], "Tive oito a Matemática.", "wiskunde = matemática.", ["v-cijfer"]),
    FE(["Mijn","dochter","zit","in","de","basisschool."], 3, "op", "op school zitten: op de basisschool.", ["v-basisschool"]),
    CO("text","A escola do Lucas", "Lucas is twaalf. Hij zit in groep acht van de basisschool. Volgend jaar gaat hij naar de middelbare school. Vandaag heeft hij een toets en hij krijgt een zeven. Zijn moeder is blij.",
       [("Que idade tem o Lucas?", ["*12","8","7"]),("Que nota teve?", ["*Sete","Oito","Doze"]),("Para onde vai no próximo ano?", ["*Para a escola secundária","Para a universidade","Fica na primária"])],
       "groep acht = último ano da primária.", ["v-toets","v-cijfer"]),
  ], diff=2, mins=6)

L(5, "A minha experiência de aprendizagem", "Revisão: escola, aulas e estudo.",
  ["Falar da sua escola e da aprendizagem"],
  ex=[("Ik zit op een taalschool en ik heb twee keer per week les.","Ando numa escola de línguas e tenho aulas duas vezes por semana.")],
  review=["v-les","v-huiswerk","v-oefenen","v-fout","v-toets","v-vraag","v-leraar","v-woordenboek"],
  cefr=C, exs=[
    TR("pt-nl","Tenho aula duas vezes por semana.", ["Ik heb twee keer per week les"], "twee keer per week.", ["v-les"]),
    TR("nl-pt","Mag ik een vraag stellen?", ["Posso fazer uma pergunta"], "een vraag stellen = fazer uma pergunta.", ["v-vraag"]),
    MC("Não percebe uma palavra durante a aula. O que pergunta?", ["*Wat betekent dit woord?","Hoe laat is de les?|Não ajuda.","Waar is de kassa?|Não faz sentido."], "Wat betekent…?", ["v-betekenen"]),
    FE(["Ik","studeer","voor","de","toets","van","morgen."], 1, "leer", "Para um teste usa-se normalmente «leren».", ["v-leren"]),
    LI("Doe je huiswerk voor donderdag.", ["Doe je huiswerk voor donderdag"], "Faz os trabalhos de casa para quinta.", "huiswerk doen/maken.", ["v-huiswerk"]),
    DL([("Professora","Heb je een vraag?","Tens uma pergunta?"),("Aluno","")], ["*Ja, kunt u dat herhalen?","Ja, een acht.|Não responde.","Nee, ik ben een vraag.|Não faz sentido."], "Pedir para repetir.", ["v-vraag","v-herhalen"]),
    CO("dialogue","Depois da aula", "Ana: Hoe was de toets?\nPedro: Moeilijk! Ik denk dat ik veel fouten heb gemaakt.\nAna: Hoeveel uur heb je geleerd?\nPedro: Maar één uur...\nAna: Volgende keer oefenen we samen!",
       [("Como correu o teste ao Pedro?", ["*Foi difícil","Foi fácil","Ainda não fez"]),("O que propõe a Ana?", ["*Praticarem juntos na próxima vez","Desistir do curso","Falar com o professor"])],
       "volgende keer = da próxima vez.", ["v-toets","v-fout","v-oefenen"]),
    WO("Uso um dicionário nas aulas.", ["Ik","gebruik","een","woordenboek","in","de","les"], "gebruiken = usar.", ["v-woordenboek"]),
    MA([("Ik begrijp het niet.","Não percebo."),("Kunt u dat herhalen?","Pode repetir?"),("Wat betekent…?","O que significa…?"),("Hoe zeg je…?","Como se diz…?")], "Frases de aula.", ["v-begrijpen","v-herhalen","v-betekenen","v-zeggen"]),
    SW("Escreva uma mensagem curta ao seu professor a dizer que não pode ir à aula e porquê.", ["Beste [leraar|meneer|mevrouw](,) ik kan [morgen|vandaag] niet naar de les komen(,) want ik ben ziek"],
       ["Começa com «Beste…»","Diz que não pode ir: «ik kan niet … komen»","Dá uma razão com «want»"], 8, "Modelo: «Beste mevrouw De Vries, ik kan morgen niet naar de les komen, want ik ben ziek. Groeten, Ana»", ["v-les"]),
  ], diff=2, mins=7)

W()
